#!/usr/bin/env python3
"""Compile shared Pebble module definitions into the MCU's retained manifest."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from control.common.modules import build_manifest

config_path = ROOT / "robots/minilamp/modules.example.json"
manifest, _ = build_manifest(json.loads(config_path.read_text()), config_path)
payload = json.dumps(manifest, separators=(",", ":"), ensure_ascii=True)
header = Path(__file__).with_name("GeneratedManifest.h")
header.write_text(
    '// Generated by generate_manifest.py; edit robots/minilamp/modules.example.json.\n'
    '#pragma once\n'
    f'constexpr char TOPIC_BASE[] = {json.dumps(manifest["base"])};\n'
    f'constexpr char MODULE_MANIFEST[] = R"PBMANIFEST({payload})PBMANIFEST";\n'
)
print(f"Generated {header.name}: {len(payload)} bytes, revision {manifest['revision']}")
